function perfectpixel_valid_initial_status( $status, $default ) {
	$status = sanitize_key( $status );
	return ( '' !== $status && array_key_exists( 'wc-' . $status, wc_get_order_statuses() ) ) ? $status : $default;
}

function perfectpixel_bacs_initial_status( $status ) {
	return perfectpixel_valid_initial_status( '{{bacs_initial_status}}', $status );
}

function perfectpixel_cheque_initial_status( $status ) {
	return perfectpixel_valid_initial_status( '{{cheque_initial_status}}', $status );
}

function perfectpixel_cod_initial_status( $status ) {
	return perfectpixel_valid_initial_status( '{{cod_initial_status}}', $status );
}
